#!/usr/bin/env bash
# Regenerates ../test/probe_contract.go from VestingDelegateProbe.sol.
# Requires solc 0.8.24 (set SOLC to its path). The generated file is committed,
# so running the repro does not need solc.
set -euo pipefail
cd "$(dirname "$0")"
SOLC="${SOLC:-solc}"
TMP="$(mktemp)"
trap 'rm -f "$TMP"' EXIT
"$SOLC" --evm-version paris --optimize --combined-json abi,bin VestingDelegateProbe.sol > "$TMP"
python3 -I - "$TMP" <<'PY'
import json, sys
d = json.load(open(sys.argv[1]))
c = d["contracts"]["VestingDelegateProbe.sol:VestingDelegateProbe"]
abi = c["abi"] if isinstance(c["abi"], str) else json.dumps(c["abi"])
out = f'''// Code generated by cases/ghsa-7g4w/contracts/gen.sh. DO NOT EDIT.
// Source: VestingDelegateProbe.sol (solc 0.8.24, --evm-version paris --optimize)

package atomicosghsa7g4w

const probeABI = `{abi}`

const probeBin = "{c["bin"]}"
'''
open("../test/probe_contract.go", "w").write(out)
print("wrote ../test/probe_contract.go")
PY
